import { strictJsonSchema, toJsonSchema } from 'xsschema';

const defineTool = ({ description, execute, name, parameters, strict }) => {
  const schema = parameters["~standard"].jsonSchema.input({ target: "draft-07" });
  return {
    execute,
    function: {
      description,
      name,
      parameters: strict !== false ? strictJsonSchema(schema) : schema,
      strict: strict ?? true
    },
    type: "function",
    validate: async (input) => parameters["~standard"].validate(input)
  };
};

const rawTool = ({ description, execute, name, parameters, strict }) => ({
  execute,
  function: {
    description,
    name,
    parameters: strict !== false ? strictJsonSchema(parameters) : parameters,
    strict: strict ?? true
  },
  type: "function"
});

const tool = async ({ description, execute, name, parameters, strict }) => {
  const schema = await toJsonSchema(parameters);
  return {
    execute,
    function: {
      description,
      name,
      parameters: strict !== false ? strictJsonSchema(schema) : schema,
      strict: strict ?? true
    },
    type: "function",
    validate: async (input) => parameters["~standard"].validate(input)
  };
};

export { defineTool, rawTool, tool };
